<?php
$localAttendanceClock=fn(?string $time)=>$time===null?'—':(new DateTimeImmutable($time,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Jakarta'))->format('d M H:i:s');
?><section class="panel" id="processed-attendance"><h2>Processed attendance records</h2><p class="muted">Persisted results from the attendance engine. Raw machine events remain unchanged. Process with <code>php bin/console.php attendance:process-logs --date=YYYY-MM-DD</code>; add <code>--dry-run</code> to preview without database changes.</p><div class="table-responsive"><table class="table"><thead><tr><th>Date / NIK</th><th>Assigned shift</th><th>Scheduled IN / OUT</th><th>Actual IN / OUT</th><th>Late / Early / Work (min)</th><th>Raw / Final status</th><th>Source / Protection</th></tr></thead><tbody><?php foreach ($persistedAttendances as $attendance):?><tr><td><?=e($attendance['attendance_date'])?><br><?=e($attendance['employee_nik'])?></td><td><?=e($attendance['shift_code']??'Unresolved')?></td><td><?=e($localAttendanceClock($attendance['scheduled_clock_in']))?><br><?=e($localAttendanceClock($attendance['scheduled_clock_out']))?></td><td><?=e($localAttendanceClock($attendance['actual_clock_in']))?><br><?=e($localAttendanceClock($attendance['actual_clock_out']))?></td><td><?=e($attendance['late_minutes']??'—')?> / <?=e($attendance['early_leave_minutes']??'—')?> / <?=e($attendance['work_minutes']??'—')?></td><td><?=e($attendance['raw_attendance_status']??'Unresolved')?><br><strong><?=e($attendance['final_attendance_status']??'Unresolved')?></strong><br><small><?=e($attendance['final_status_source'])?></small></td><td><?php $calculated=json_decode($attendance['calculated_payload'],true);?><details><summary><?=e($attendance['raw_log_count'])?> raw logs</summary><code><?=e(implode(', ',$calculated['source_log_ids']??[]))?></code><?php foreach ($calculated['issues']??[] as $issue):?><div class="validation"><?=e($issue)?></div><?php endforeach;?></details><?php if (AttendanceProcessor::truth($attendance['hr_manually_corrected'])||AttendanceProcessor::truth($attendance['is_confirmed'])||!empty($attendance['approved_request_id'])):?><span class="badge text-bg-warning">HR protected</span><?php endif;?></td></tr><?php endforeach;?><?php if (!$persistedAttendances):?><tr><td colspan="7" class="muted">No employee attendance records processed. Configure the real employee/shift policy first; unmapped raw cards stay in manual review.</td></tr><?php endif;?></tbody></table></div></section>
